SortAlgorithm is a design pattern that defines the skeleton of an algorithm, deferring some of the steps to subclasses.  Here's a Python implementation of the Template Method pattern for sorting algorithms:

```python
from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def sort(self):
        """
        Template method for sorting.
        """
        self._validate_data()
        for i in range(len(self.data) - 1):
            for j in range(len(self.data) - 1 - i):
                if self.compare(self.data[j], self.data[j+1]) > 0:
                    self._swap(j, j+1)
        return self.data

    def compare(self, a, b):
        """
        Abstract method to compare two elements.
        """
        raise NotImplementedError("Compare method must be implemented in subclasses")

    def swap(self, i, j):
        """
        Abstract method to swap two elements.
        """
        raise NotImplementedError("Swap method must be implemented in subclasses")

    def _validate_data(self):
        """
        Placeholder for data validation.
        """
        pass

    def _swap(self, i, j):
        """
        Placeholder for swapping elements.
        """
        pass


class BubbleSort(SortAlgorithm):
    def __init__(self, data):
        self.data = data

    def compare(self, a, b):
        if a < b:
            return -1
        elif a > b:
            return 1
        else:
            return 0

    def swap(self, i, j):
        a = self.data[i]
        b = self.data[j]
        self.data[i] = b
        self.data[j] = a


class SelectionSort(SortAlgorithm):
    def __init__(self, data):
        self.data = data

    def compare(self, a, b):
        if a < b:
            return -1
        elif a > b:
            return 1
        else:
            return 0

    def swap(self, i, j):
        a = self.data[i]
        b = self.data[j]
        self.data[i] = b
        self.data[j] = a


# Example usage (testing)
if __name__ == "__main__":
    # Test Bubble Sort
    bubble_sort = BubbleSort([5, 1, 4, 2, 8])
    sorted_bubble = bubble_sort.sort()
    print(f"Bubble Sort: {sorted_bubble}")  # Output: [1, 2, 4, 5, 8]

    # Test Selection Sort
    selection_sort = SelectionSort([64, 25, 12, 22, 11])
    sorted_selection = selection_sort.sort()
    print(f"Selection Sort: {sorted_selection}")  # Output: [11, 12, 22, 25, 64]
